    if delim, ok := tok.(json.Delim); !ok || delim != '{' {
        // Not an object: consume any remainder and let the regular parse
        // report the type problem.
        return skipRest(dec, tok)
    }
    seen := make(map[string]bool, len(spec.descend)+2)
    for dec.More() {
        key, err := scanKey(dec)
        if err != nil {
            return err
        }
        field, known := spec.field(key)
        if known {
            if seen[field] {
                return duplicateFieldError(field, spec.location)
            }
            seen[field] = true
        }
        if scan, ok := spec.descend[field]; ok && known {
            if err := scan(dec); err != nil {
                return err
            }
        } else if err := skipValue(dec); err != nil {
            return err
        }
    }
    _, err = scanToken(dec) // closing '}'
    return err
}
```

